from jsonb_array_elements('[{"s":"koi","n":"Koi","l":"Cyprinus rubrofuscus","d":"Kolay","t":"Barışçıl","x":"Japonya''da yüzyıllar boyunca renk ve desen için ıslah edilmiş süs sazanı. Kohaku, Sanke, Showa gibi çok sayıda varyetesi vardır; çoğunlukla havuzda tutulur.","f":["60–90 cm","4–28 °C","7.0–8.5","3000 L","Barışçıl","Hepçil: koi peleti, sebze","Yumurtlayan (bitkilere)","Doğu Asya (Japonya''da ıslah)","25–35 yıl","Havuz balığı"],"k":["koi","koi balığı","nishikigoi","süs sazanı","cyprinus rubrofuscus"],"c":"Akvaryum için fazla iri olur; derin, iyi filtreli bir havuz ister.","a":[[33,115,1500,"Doğu Asya"]],"m":"Koi''ler eskiden Cyprinus carpio içinde sayılırdı; bugün Doğu Asya sazanı C. rubrofuscus''tan ıslah edildiği kabul edilir.","g":"sazangiller"},{"s":"flowerhorn","n":"Flowerhorn","l":"Hibrit (Amphilophus, Vieja vb.)","d":"Kolay","t":"Çok agresif","x":"Orta Amerika ciklitlerinin melezlenmesiyle Malezya ve Tayvan''da ıslah edilmiş, alnındaki büyük çıkıntı (kok) ve renkli pullarıyla tanınan hibrit bir ciklet.","f":["30–40 cm","26–30 °C","7.0–8.0","300 L","Çok agresif","Etçil ağırlıklı hepçil: ciklet peleti","Substrata yumurtlayan","Güneydoğu Asya''da ıslah (hibrit)","10–12 yıl","Alın çıkıntısı (kok)"],"k":["flowerhorn","flower horn","luo han","kok ciklet"],"c":"Çok saldırgandır; genellikle tankta tek başına tutulur. Doğaya kesinlikle bırakılmamalı.","a":[],"m":"Doğada bulunmayan, insan eliyle üretilmiş bir hibrittir.","g":"orta-amerika"},{"s":"blood-parrot","n":"Papağan Balığı (Blood Parrot)","l":"Hibrit (Amphilophus × Vieja vb.)","d":"Kolay","t":"Yarı agresif","x":"Tayvan''da ıslah edilmiş, yuvarlak gövdeli ve tam kapanmayan gaga biçimli ağzıyla tanınan hibrit bir ciklet. Turuncu, kırmızı ve sarı tonlarda satılır.","f":["20 cm","25–28 °C","6.5–7.5","200 L","Yarı agresif","Hepçil: batan ciklet peleti","Yumurtlayan (çoğu kısır)","Tayvan''da ıslah (hibrit)","10–15 yıl","Kapanmayan gaga ağız"],"k":["blood parrot","papağan balığı","parrot cichlid","papagan","red parrot"],"c":"Boyanmış ya da dövme yapılmış bireylerden uzak dur; ağız yapısı yüzünden batan yemle beslenmeli.","a":[],"m":"Deniz papağan balıkları (Scaridae) ile ilgisi yoktur; insan eliyle üretilmiş bir hibrittir.","g":"orta-amerika"},{"s":"gyrinocheilus-aymonieri","n":"Çin Yosun Yiyicisi","l":"Gyrinocheilus aymonieri","d":"Kolay","t":"Yarı agresif","x":"Vantuz gibi ağzıyla camlara ve taşlara tutunup yosun kazıyan bir tür. Altın (gold) formu Türkiye''de çok yaygındır.","f":["25 cm","22–28 °C","6.5–7.5","200 L","Yarı agresif","Otçul: yosun, sebze, tablet","Yumurtlayan (akvaryumda nadir)","Güneydoğu Asya","10 yıl","Vantuz ağız"],"k":["chinese algae eater","çin yosun yiyicisi","gold algae eater","gyrinocheilus aymonieri","yosun yiyici"],"c":"Büyüdükçe yosun yemeyi bırakıp diğer balıkların derisini kazımaya başlayabilir.","a":[[13,103,900,"Güneydoğu Asya (Hindiçin)"]],"m":"Siyam yosun yiyicisi (Crossocheilus) ile karıştırılmamalı.","g":"sazangiller"},{"s":"scleropages-formosus","n":"Asya Arowanası","l":"Scleropages formosus","d":"Zor","t":"Agresif","x":"Kırmızı, altın ve yeşil formlarıyla ''ejderha balığı'' olarak bilinen, Asya''da şans getirdiğine inanılan iri bir arowana.","f":["90 cm","24–30 °C","6.0–7.0","1500 L","Agresif","Etçil: balık, karides, böcek","Ağız kuluçkacı (erkek)","Güneydoğu Asya","20+ yıl","Ejderha balığı"],"k":["asian arowana","asya arowanası","dragon fish","ejderha balığı","scleropages formosus","arowana"],"c":"Nesli tehlikede olduğu için CITES kapsamındadır; yalnızca belgeli ve çipli çiftlik üretimi bireyler yasal olarak satılabilir. Çok büyük ve kapaklı tank ister.","a":[[0,113,700,"Borneo ve Sumatra"]],"m":null,"g":"ilkel-siradisi-baliklar"},{"s":"pangasianodon-hypophthalmus","n":"Pangasius (Köpekbalığı Kedi Balığı)","l":"Pangasianodon hypophthalmus","d":"Zor","t":"Barışçıl","x":"Türkiye''de küçükken ''köpekbalığı'' adıyla satılan, gerçekte 1 metreyi aşan bir kedi balığı. Ürkek ve hızlı yüzer, camlara çarparak yaralanabilir.","f":["130 cm","22–28 °C","6.5–7.5","3000 L","Barışçıl","Hepçil","Göç ederek yumurtlayan (akvaryumda yok)","Mekong ve Chao Phraya havzaları","15–20 yıl","Çok iri, ürkek sürü balığı"],"k":["iridescent shark","pangasius","köpekbalığı","akvaryum köpekbalığı","pangasianodon hypophthalmus"],"c":"Ev akvaryumu için uygun değildir; birkaç ayda çok hızlı büyür.","a":[[14,105,600,"Mekong havzası"]],"m":null,"g":"kedi-baliklari"},{"s":"metynnis-argenteus","n":"Gümüş Dolar","l":"Metynnis argenteus","d":"Kolay","t":"Barışçıl","x":"Yuvarlak, yassı ve gümüşi gövdesiyle sürü hâlinde yüzen, piranhaların otçul akrabası.","f":["15 cm","24–28 °C","6.0–7.5","300 L","Barışçıl","Otçul: sebze, spirulina","Yumurtlayan","Amazon ve Guyana","10 yıl","Bitki yer"],"k":["silver dollar","gümüş dolar","metynnis argenteus","metynnis"],"c":"Canlı bitkileri yer; sürü hâlinde (5+) ve geniş tankta tut.","a":[[-3,-62,900,"Amazon havzası"],[4,-57,400,"Guyana kalkanı"]],"m":null,"g":"characiformlar"},{"s":"colossoma-macropomum","n":"Tambaqui (Siyah Pacu)","l":"Colossoma macropomum","d":"Zor","t":"Barışçıl","x":"Küçükken piranhaya benzeyen, ama meyve ve tohumla beslenen ve 1 metreye ulaşan iri bir characin.","f":["100 cm","24–30 °C","6.0–7.5","3000 L","Barışçıl","Hepçil: meyve, tohum, pelet","Göç ederek yumurtlayan","Amazon ve Orinoko","20+ yıl","Çok iri büyür"],"k":["tambaqui","black pacu","siyah pacu","colossoma macropomum","pacu"],"c":"Ev akvaryumu için uygun değildir; küçükken satılır ama hızla devleşir.","a":[[-3,-62,900,"Amazon havzası"],[6,-66,500,"Orinoko havzası"]],"m":null,"g":"characiformlar"},{"s":"leporinus-fasciatus","n":"Leporinus","l":"Leporinus fasciatus","d":"Orta","t":"Yarı agresif","x":"Sarı gövdesinde siyah dikey bantlar taşıyan, aşağı doğru eğik yüzen hareketli bir characin.","f":["30 cm","23–27 °C","6.0–7.5","400 L","Yarı agresif","Hepçil: sebze ve pelet","Yumurtlayan","Amazon ve Orinoko","10–15 yıl","Siyah-sarı bantlı"],"k":["leporinus","banded leporinus","leporinus fasciatus"],"c":"Bitkileri yer, zıplam